  private void login(String email,String password,TextView message){busy=true;message.setText("Signing in securely…");final int g=++generation;io.execute(()->{try{JSONObject payload=new JSONObject();payload.put("email",email);payload.put("password",password);payload.put("returnSecureToken",true);JSONObject auth=request("https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key="+API_KEY,"POST",payload.toString(),null);String id=auth.getString("localId"),access=auth.getString("idToken"),rt=auth.getString("refreshToken");JSONObject records=readAccounting(id,access);runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;uid=id;token=access;refresh=rt;data=records;status="Cloud verified";locked=false;open("Home");});}catch(Exception ex){runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;message.setText("Sign-in or cloud read failed. Check credentials, internet and account permissions.");});}});}
  private JSONObject request(String url,String method,String payload,String bearer)throws Exception{
    HttpsURLConnection c=(HttpsURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(bearer!=null)c.setRequestProperty("Authorization","Bearer "+bearer);
    try{if(payload!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(payload.getBytes(StandardCharsets.UTF_8));}}if(c.getResponseCode()<200||c.getResponseCode()>=300)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(out.size()+n>3000000)throw new IOException("Response too large");out.write(buf,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}
  }
  private JSONObject readAccounting(String id,String access)throws Exception{JSONObject doc=request("https://firestore.googleapis.com/v1/projects/"+PROJECT+"/databases/(default)/documents/owners/"+id+"/settings/biki_accounting_v1","GET",null,access);JSONObject result=new JSONObject(doc.getJSONObject("fields").getJSONObject("value").getString("stringValue"));if(result.optJSONArray("sales")==null||result.optJSONArray("transactions")==null||result.optJSONArray("dues")==null)throw new IOException("Unrecognized record schema");return result;}
  private void refreshCloud(){if(uid.isEmpty()||busy||locked)return;busy=true;final int g=generation;final String id=uid,access=token;status="Refreshing…";open(page);io.execute(()->{try{JSONObject latest=readAccounting(id,access);runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;data=latest;status="Cloud verified";if(!locked)open(page);});}catch(Exception e){runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;status="Refresh failed — showing last verified data";if(!locked)open(page);});}});}
  private void biometric(){if(uid.isEmpty()||!locked){new AlertDialog.Builder(this).setTitle("Fingerprint Login").setMessage("First verify your existing cloud account using your password. This development build can unlock an active session only; it does not store login credentials.").setPositiveButton("OK",null).show();return;}if(Build.VERSION.SDK_INT<28){signOut();return;}try{new BiometricPrompt.Builder(this).setTitle("BIKI Billing PRO").setSubtitle("Unlock your business workspace").setNegativeButton("Use password",getMainExecutor(),(d,w)->signOut()).build().authenticate(new CancellationSignal(),getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){locked=false;open("Home");}@Override public void onAuthenticationError(int n,CharSequence s){Toast.makeText(MainActivity.this,s,Toast.LENGTH_SHORT).show();}});}catch(Exception e){signOut();}}
