  private View glyph(String kind,int color,int size){View v=new View(this){final Paint p=new Paint(3);protected void onDraw(Canvas c){super.onDraw(c);c.save();float u=Math.min(getWidth(),getHeight())/24f;c.translate((getWidth()-24*u)/2,(getHeight()-24*u)/2);c.scale(u,u);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.7f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);android.graphics.Path a=new android.graphics.Path();switch(kind){case "Home":a.moveTo(3,11);a.lineTo(12,3);a.lineTo(21,11);a.moveTo(5,10);a.lineTo(5,21);a.lineTo(10,21);a.lineTo(10,15);a.lineTo(14,15);a.lineTo(14,21);a.lineTo(19,21);a.lineTo(19,10);break;case "Sale":c.drawRoundRect(4,7,20,21,3,3,p);c.drawArc(8,3,16,11,180,180,false,p);break;case "Due":case "Cash":c.drawRoundRect(3,5,21,19,3,3,p);c.drawRoundRect(14,10,22,15,2,2,p);break;case "More":for(int x=3;x<17;x+=10)for(int y=3;y<17;y+=10)c.drawRoundRect(x,y,x+7,y+7,2,2,p);break;case "Customer":case "User":c.drawCircle(12,7,4,p);c.drawArc(4,13,20,25,190,160,false,p);break;case "Ticket":c.drawRoundRect(3,6,21,18,2,2,p);c.drawLine(15,6,15,18,p);break;case "Bank":a.moveTo(2,8);a.lineTo(12,3);a.lineTo(22,8);a.close();c.drawLine(3,21,21,21,p);for(int x=6;x<=18;x+=6)c.drawLine(x,10,x,18,p);break;case "Plus":c.drawLine(5,12,19,12,p);c.drawLine(12,5,12,19,p);break;case "Bell":a.moveTo(4,18);a.lineTo(6,15);a.lineTo(6,10);a.quadTo(6,4,12,4);a.quadTo(18,4,18,10);a.lineTo(18,15);a.lineTo(20,18);a.close();c.drawArc(10,18,14,22,0,180,false,p);break;case "Profit":a.moveTo(3,17);a.lineTo(10,10);a.lineTo(14,14);a.lineTo(21,5);a.moveTo(15,5);a.lineTo(21,5);a.lineTo(21,11);break;case "Clock":c.drawCircle(12,12,9,p);c.drawLine(12,12,12,6,p);c.drawLine(12,12,16,14,p);break;case "Expense":c.drawRoundRect(2,5,22,19,2,2,p);c.drawCircle(12,12,3,p);break;case "Back":a.moveTo(13,5);a.lineTo(6,12);a.lineTo(13,19);a.moveTo(6,12);a.lineTo(21,12);break;default:c.drawRoundRect(5,3,19,21,2,2,p);c.drawLine(8,8,16,8,p);c.drawLine(8,12,16,12,p);c.drawLine(8,16,14,16,p);}c.drawPath(a,p);c.restore();}};v.setLayoutParams(new LinearLayout.LayoutParams(dp(size),dp(size)));return v;}
