  private void navBar(){nav=row();nav.setPadding(dp(10),dp(8),dp(10),dp(8));nav.setBackgroundColor(0xff191a17);String[] labels={"Home","Sale","Due","More"},routes={"Home","New Sale","Due Management","More"};for(int i=0;i<4;i++){final String route=routes[i];boolean on=page.equals(route);int color=on?0xffe4c383:0xff92948b;LinearLayout tab=column();tab.setGravity(Gravity.CENTER);FrameLayout capsule=new FrameLayout(this);capsule.setBackground(shape(on?0xff3b3020:0xff191a17,0,10));View icon=glyph(labels[i],color,23);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(dp(23),dp(23),Gravity.CENTER);capsule.addView(icon,ip);tab.addView(capsule,new LinearLayout.LayoutParams(dp(52),dp(34)));gap(tab,3);TextView t=inline(labels[i],12,color,on);t.setGravity(Gravity.CENTER);tab.addView(t);tab.setContentDescription(labels[i]);tab.setOnClickListener(v->open(route));nav.addView(tab,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav,new LinearLayout.LayoutParams(-1,-2));}
